/-- `H(w)`: the coverages of the nonempty factors of `w`. -/
def word_factor_coverages {α : Type*} [DecidableEq α] (w : List α) : Set (Finset ℕ) :=
  {C | ∃ x : List α, x ≠ [] ∧ x <:+: w ∧ word_occurrence_coverage w x = C}

/-- `H_min(w)`: the inclusion-minimal factor coverages of `w`. -/
def word_min_factor_coverages {α : Type*} [DecidableEq α] (w : List α) : Set (Finset ℕ) :=
  {C | C ∈ word_factor_coverages w ∧ ∀ D ∈ word_factor_coverages w, D ⊆ C → D = C}

/-- One pebbling step `c ⟶ c'` on `G`: along some edge `uv` with `c u ≥ 2`, remove two pebbles from `u` and add one to `v`. -/
def graph_pebbling_step {V : Type*} [DecidableEq V] (G : SimpleGraph V) (c c' : V → ℕ) : Prop :=
  ∃ u v, G.Adj u v ∧ 2 ≤ c u ∧ c' = Function.update (Function.update c u (c u - 2)) v (c v + 1)

