/-- A minimal zero-sum sequence. -/
def multiset_is_minimal_zero_sum {G : Type*} [AddCommMonoid G] (s : Multiset G) : Prop :=
  s ≠ 0 ∧ s.sum = 0 ∧ ∀ t ≤ s, t ≠ 0 → t.sum = 0 → t = s

/-- `q(m)`: the smallest prime not dividing `m`. -/
noncomputable def nat_least_prime_not_dvd (m : ℕ) : ℕ :=
  sInf {p | p.Prime ∧ ¬ p ∣ m}

/-- The eight symmetries of the square. -/
def int_square_symmetry (e₁ e₂ : ℤˣ) (sw : Bool) (v : ℤ × ℤ) : ℤ × ℤ :=
  if sw then ((e₁ : ℤ) * v.2, (e₂ : ℤ) * v.1) else ((e₁ : ℤ) * v.1, (e₂ : ℤ) * v.2)

/-- A hop of `G`: a permutation sending every vertex to one of its neighbours. -/
def simple_graph_is_hop {V : Type*} (G : SimpleGraph V) (h : Equiv.Perm V) : Prop :=
  ∀ v, G.Adj v (h v)

/-- The leap group `Λ₁(G)`: the subgroup of `Equiv.Perm V` generated by the hops of `G`. -/
def simple_graph_leap_group {V : Type*} (G : SimpleGraph V) : Subgroup (Equiv.Perm V) :=
  Subgroup.closure {h | simple_graph_is_hop G h}

/-- Unit cells of the rectangle `[x₀,x₁]×[y₀,y₁]`, given as `(x₀, x₁, y₀, y₁)`. -/
def mondrian_rect_cells (r : ℕ × ℕ × ℕ × ℕ) : Finset (ℕ × ℕ) :=
  Finset.Ico r.1 r.2.1 ×ˢ Finset.Ico r.2.2.1 r.2.2.2

/-- Width `x₁ - x₀`. -/
def mondrian_rect_width (r : ℕ × ℕ × ℕ × ℕ) : ℕ :=
  r.2.1 - r.1

/-- Height `y₁ - y₀`. -/
def mondrian_rect_height (r : ℕ × ℕ × ℕ × ℕ) : ℕ :=
  r.2.2.2 - r.2.2.1

/-- Area `|R|`. -/
def mondrian_rect_area (r : ℕ × ℕ × ℕ × ℕ) : ℕ :=
  mondrian_rect_width r * mondrian_rect_height r

/-- The defect: largest minus smallest rectangle area. -/
def mondrian_defect (P : List (ℕ × ℕ × ℕ × ℕ)) : ℕ :=
  ((P.map mondrian_rect_area).max?.getD 0) - ((P.map mondrian_rect_area).min?.getD 0)

/-- Admissible modulo `n`: no term of `A` is `≡ 0 (mod n)`. -/
def zero_sum_admissible (n : ℕ) {r : ℕ} (A : List (Fin r → ℤ)) : Prop :=
  ∀ a ∈ A, ∃ j, ¬ (n : ℤ) ∣ a j

/-- Positions `I` whose sum is `≡ 0 (mod n)` but `≢ 0 (mod n²)`. -/
def zero_sum_good_subseq (n : ℕ) {r : ℕ} (A : List (Fin r → ℤ)) (I : Finset (Fin A.length)) : Prop :=
  I.Nonempty ∧ (∀ j, (n : ℤ) ∣ ∑ i ∈ I, A.get i j) ∧ ∃ j, ¬ ((n : ℤ) ^ 2 ∣ ∑ i ∈ I, A.get i j)

/-- `w`-bad: admissible, and no nonempty subsequence satisfies (1.2). -/
def zero_sum_w_bad (n : ℕ) {r : ℕ} (A : List (Fin r → ℤ)) : Prop :=
  zero_sum_admissible n A ∧ ∀ I, ¬ zero_sum_good_subseq n A I

/-- The wild number `wld_γ(G)`: the least size of a finite colour-connecting set (0 if there is none, which cannot happen for a finite connected graph). -/
noncomputable def simple_graph_wild_number {V α : Type*} (G : SimpleGraph V) (γ : G.edgeSet → α) : ℕ :=
  sInf {k | ∃ W : Finset (Sym2 V), W.card = k ∧ simple_graph_is_color_connecting G γ ↑W}

/-- The number of arcs of a finite digraph (ordered pairs `(u, v)` with `G.Adj u v`). -/
def digraph_edge_count {V : Type*} [Fintype V] (G : Digraph V) [DecidableRel G.Adj] : ℕ :=
  (Finset.univ.filter fun p : V × V => G.Adj p.1 p.2).card

/-- The bundle `A_i` of agent `i` in the complete allocation `A : M → N`. -/
def allocation_bundle {N M : Type*} [Fintype M] [DecidableEq N] (A : M → N) (i : N) : Finset M :=
  Finset.univ.filter fun g => A g = i

/-- A complete mapping: `θ` and `x ↦ x * θ x` are both bijections of `G`. -/
def group_is_complete_mapping {G : Type*} [Group G] (θ : G → G) : Prop :=
  Function.Bijective θ ∧ Function.Bijective fun x => x * θ x

/-- Bidirected `K_{d+1}` on `0, …, d` plus an apex `d + 1` with arcs to all of them (no arcs into the apex). -/
def digraph_apex_over_bidirected_complete (d : ℕ) : Digraph (Fin (d + 2)) :=
  { Adj := fun u v => u ≠ v ∧ v ≠ Fin.last (d + 1) }

