/-- `(E, A)` is a mixed graph: `A` is irreflexive and asymmetric (no antiparallel arcs) and no arc joins two vertices joined by an edge. `E` is a `SimpleGraph`, so it has no loops or parallel edges. -/
def mixed_graph_is_valid {V : Type*} (E : SimpleGraph V) (A : V → V → Prop) : Prop :=
  (∀ x, ¬ A x x) ∧ (∀ x y, A x y → ¬ A y x) ∧ ∀ x y, E.Adj x y → ¬ A x y

/-- `(E, A)` is `(r, z)`-regular: every vertex has degree `r` in `E`, out-degree `z` and in-degree `z` in `A` (cardinalities as `Set.ncard`, meant for finite `V`). -/
def mixed_graph_is_regular {V : Type*} (E : SimpleGraph V) (A : V → V → Prop) (r z : ℕ) : Prop :=
  ∀ x, {y | E.Adj x y}.ncard = r ∧ {y | A x y}.ncard = z ∧ {y | A y x}.ncard = z

/-- `(E, A)` has girth `g`: a `g`-cycle exists and no `t`-cycle with `t < g` does. -/
def mixed_graph_has_girth {V : Type*} (E : SimpleGraph V) (A : V → V → Prop) (g : ℕ) : Prop :=
  mixed_graph_has_cycle E A g ∧ ∀ t < g, ¬ mixed_graph_has_cycle E A t

/-- `L` is a Latin square of order `n`: every row `L i` and every column `fun i => L i j` is injective, hence a permutation of `Fin n`. -/
def latin_square_is {n : ℕ} (L : Fin n → Fin n → Fin n) : Prop :=
  (∀ i, Function.Injective (L i)) ∧ ∀ j, Function.Injective fun i => L i j

/-- `m ∈ hA`: `m` is the sum of `h` (not necessarily distinct) elements of the finite set `A ⊆ ℤ`. -/
def int_mem_h_fold_sumset (h : ℕ) (A : Finset ℤ) (m : ℤ) : Prop :=
  ∃ f : Fin h → ℤ, (∀ i, f i ∈ A) ∧ ∑ i, f i = m

/-- `n_h(A)`: the largest `n` with `[0, n] ⊆ hA`. The set of such `n` is bounded since `hA` is finite; it is `0` (not `-1`) when `0 ∉ hA`, which only matters for sets that are no basis at all. -/
noncomputable def postage_stamp_basis_range (h : ℕ) (A : Finset ℤ) : ℕ :=
  sSup {n : ℕ | ∀ m : ℕ, m ≤ n → int_mem_h_fold_sumset h A m}

/-- `n_h(k)`: the largest `n_h(A)` over `(k+1)`-element sets `A` of nonnegative integers. -/
noncomputable def postage_stamp_number (h k : ℕ) : ℕ :=
  sSup {n | ∃ A : Finset ℤ, A.card = k + 1 ∧ (∀ a ∈ A, 0 ≤ a) ∧ postage_stamp_basis_range h A = n}

/-- `n♭_h(k)`: the largest `n_h(A)` over `(k+1)`-element sets `A ⊆ ℤ` with a negative element. -/
noncomputable def postage_stamp_number_neg (h k : ℕ) : ℕ :=
  sSup {n | ∃ A : Finset ℤ, A.card = k + 1 ∧ (∃ a ∈ A, a < 0) ∧ postage_stamp_basis_range h A = n}

