def cyclic_four_block_dst (m : ℕ) (e : (Fin (2*m+5) × Fin 6)) : ℕ :=
  ![4*e.1.val+1,4*e.1.val+2,4*e.1.val+3,
    4*(cyclic_four_block_next m e.1).val+1,
    if e.1.val+1 = (2*m+5) then 3 else 4*(e.1.val+1)+2,
    if e.1.val+1 = (2*m+5) then 2 else 4*(e.1.val+1)+3] e.2

def cyclic_four_block_touch (m : ℕ) (e f : (Fin (2*m+5) × Fin 6)) : Prop :=
  cyclic_four_block_src m e = cyclic_four_block_src m f ∨ cyclic_four_block_src m e = cyclic_four_block_dst m f ∨
  cyclic_four_block_dst m e = cyclic_four_block_src m f ∨ cyclic_four_block_dst m e = cyclic_four_block_dst m f

def cyclic_four_block_good (m : ℕ) (e : (Fin (2*m+5) × Fin 6)) : Prop :=
  e.2.val = 1 ∨ e.2.val = 2 ∨ (e.2.val = 0 ∧ 0<e.1.val ∧ e.1.val+1 < (2*m+5)) ∨
    (e.2.val = 3 ∧ e.1.val+2=(2*m+5))

def cyclic_four_block_W (m : ℕ) (e : (Fin (2*m+5) × Fin 6)) : (Fin (2*m+5) × Fin 6) :=
  let i := e.1
  ![(i,(⟨1,by decide⟩ : Fin 6)),(i,(⟨2,by decide⟩ : Fin 6)),(i,(⟨1,by decide⟩ : Fin 6)),
    if i.val+1=(2*m+5) then (cyclic_four_block_prev m i,(⟨3,by decide⟩ : Fin 6))
    else if i.val=0 then (cyclic_four_block_next m i,(⟨0,by decide⟩ : Fin 6)) else (i,(⟨0,by decide⟩ : Fin 6)),
    (i,(⟨1,by decide⟩ : Fin 6)),(i,(⟨2,by decide⟩ : Fin 6))] e.2

/-- The best guaranteed EF1 approximation factor for a picking sequence seq with n agents is the supremum of factors α guaranteed for seq. -/
noncomputable def picking_sequence_alpha (n : ℕ) (seq : List (Fin n)) : ℝ :=
