- w = 0: J = {0, 1, 2, 3, 4, 5}, with |I ∩ J| = 6, yielding 128 - 2^7 = 0;
- w = 64: J = {0, 1, 2, 3, 4, 6}, with |I ∩ J| = 5, yielding 128 - 2^6 = 64;
- w = 96: J = {0, 1, 2, 3, 6, 7}, with |I ∩ J| = 4, yielding 128 - 2^5 = 96;
